PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'STUDENT' CHECK(role IN ('ADMIN','FACULTY','STUDENT')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,department TEXT NOT NULL DEFAULT 'Information Technology');
CREATE TABLE IF NOT EXISTS notices (id TEXT PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'General',priority TEXT NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high')),class_code TEXT,attachment_url TEXT,expires_at TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS timetable (id INTEGER PRIMARY KEY AUTOINCREMENT,class_code TEXT NOT NULL,day TEXT NOT NULL,period TEXT NOT NULL,subject TEXT NOT NULL,faculty TEXT,room TEXT,FOREIGN KEY(class_code) REFERENCES classes(code) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS faculty (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,department TEXT NOT NULL DEFAULT 'Information Technology',subject TEXT,room TEXT,availability TEXT DEFAULT 'Available',photo TEXT);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
INSERT OR IGNORE INTO classes(code,name) VALUES ('IT-A','IT-A'),('IT-B','IT-B'),('IT-C','IT-C');
